actions.script:
def result = ec.service.sync().name('zenith.pos.PosCreditServices.list#PosCreditBills')
    .parameters([sourceModuleId:creditModule,search:ec.web.parameters.search]).call()
if (ec.message.hasError()) {
    def error = ec.message.errorsString
    ec.message.clearErrors()
    ec.web.sendJsonResponse([success:false,error:error])
} else {
    ec.web.sendJsonResponse(result.creditList)
}

def p = ec.web.parameters
def result = ec.service.sync().name('zenith.pos.PosCreditServices.settle#ScopedPosCredit')
    .parameters([sourceModuleId:creditModule,transactionId:p.settleTxId,paymentMethod:p.settleMethod,
        amount:p.settleAmount,referenceNumber:p.settleRef,collectionSessionId:p.sessionId]).call()
if (ec.message.hasError()) {
    def error = ec.message.errorsString
    ec.transaction.setRollbackOnly('Credit settlement rejected',null)
    ec.message.clearErrors()
    ec.web.sendJsonResponse([success:false,error:error])
} else {
    ec.web.sendJsonResponse([success:true,outstanding:result.outstanding,fullyPaid:result.fullyPaid,paidAmount:result.paidAmount])
}

def result = ec.service.sync().name('zenith.pos.PosCreditServices.get#PosCreditHistory')
    .parameters([transactionId:ec.web.parameters.transactionId,sourceModuleId:creditModule]).call()
def success = !ec.message.hasError(); def error = ec.message.errorsString; ec.message.clearErrors()
ec.web.sendJsonResponse([success:success,error:error,history:result?.history])

creditBilling = true
creditTransactions = true
if (creditModule == 'kot') {
    def role = ec.service.sync().name('zenith.base.RoleAccessServices.get#AssignedRoleScope').disableAuthz().call()
    if (role.restricted && !role.legacyModules.contains('kot')) {
        creditBilling = role.selections.kot?.contains('/kot/KotBilling') == true
        creditTransactions = role.selections.kot?.contains('/kot/PosTransactions') == true
    }
}
